async function main() {
  widget.render(ui.canvas({ key: "scene", gpu: true, height: 100 }))
  __host.post({ type: "gpu", ops: [["sampler", 1, { addressModeU: "wrap", addressModeV: "repeat", addressModeW: "repeat", magFilter: "nearest", minFilter: "nearest", mipmapFilter: "nearest", lodMinClamp: 0, lodMaxClamp: 32, compare: null, maxAnisotropy: 1 }]], bytes: new ArrayBuffer(8) })
  await widget.frame()
}
